﻿function ConvertTo-MtAffectedObjectRecord {
    <#
    .SYNOPSIS
    Converts Graph objects passed to Add-MtTestResultDetail into normalized affected objects records.

    .DESCRIPTION
    Produces one record per Graph object with a stable schema:
    System / AnchorKind / Type / Id / DisplayName / PortalLink / Source.

    AnchorKind is 'Instance' when the object has its own portal deep link,
    'Surface' when the type only maps to a tenant-level settings page.
    Objects of unknown type still yield a record (AnchorKind 'Instance' when an id
    is present) so no referenced entity is silently dropped.
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param(
        # Collection of Graph objects referenced by a test result.
        [Parameter(Mandatory = $true)]
        [Object[]] $GraphObjects,

        # The declared GraphObjectType. If empty, the type is inferred per object from @odata.type.
        [Parameter(Mandatory = $false)]
        [string] $GraphObjectType
    )

    $portalLinkTemplate = Get-MtPortalLinkTemplate

    # GraphObjectType → canonical object type. Must match the type names emitted by
    # Get-MtAffectedObjectFromMarkdown so records from both sources dedupe correctly.
    $canonicalType = @{
        ConditionalAccess = 'ConditionalAccessPolicy'
        Users             = 'User'
        UserRole          = 'User'
        Groups            = 'Group'
        Devices           = 'Device'
    }

    # GraphObjectType whose objects are really another type: the check links to a settings blade
    # but passes the affected objects. IdentityProtection results are the users at risk.
    $objectTypeAlias = @{
        IdentityProtection = 'Users'
    }

    # Kept out of Get-MtPortalLinkTemplate: Get-GraphObjectMarkdown would render these types without a link.
    # Applications are absent because markdown deep links identify them by appId, not object id.
    $odataObjectType = @{
        '#microsoft.graph.servicePrincipal'        = 'ServicePrincipal'
        '#microsoft.graph.directoryRole'           = 'DirectoryRole'
        '#microsoft.graph.conditionalAccessPolicy' = 'ConditionalAccessPolicy'
    }

    $records = foreach ($item in $GraphObjects) {
        $id = Get-ObjectProperty $item 'id'
        $displayName = Get-ObjectProperty $item 'displayName'
        $userPrincipalName = Get-ObjectProperty $item 'userPrincipalName'
        if ([string]::IsNullOrWhiteSpace($displayName) -and $GraphObjectType -eq 'Users') {
            $displayName = $userPrincipalName
        }
        $odataType = Get-ObjectProperty $item '@odata.type'

        $type = $GraphObjectType
        if (-not $type -and $odataType -and $portalLinkTemplate.OdataTypeMapping.ContainsKey($odataType)) {
            $type = $portalLinkTemplate.OdataTypeMapping[$odataType]
        }
        if ($type -and $objectTypeAlias.ContainsKey($type)) {
            $type = $objectTypeAlias[$type]
        }

        $portalLink = $null
        if ($type -and $portalLinkTemplate.LinkTemplates.ContainsKey($type)) {
            $template = $portalLinkTemplate.LinkTemplates[$type]
            # A per-object template without the id would open a broken blade.
            if ($id -or -not $template.Contains('{0}')) {
                $portalLink = $template -f $id
            }
        }

        if ($type -and $portalLinkTemplate.InstanceTypes -contains $type) {
            # Without an id the object is not addressable, and every id-less record would merge into one object.
            $anchorKind = if ($id) { 'Instance' } else { 'Unknown' }
        } elseif ($type) {
            $anchorKind = 'Surface'
        } elseif ($id) {
            $anchorKind = 'Instance'
        } else {
            $anchorKind = 'Unknown'
        }

        [PSCustomObject]@{
            System            = 'EntraID'
            AnchorKind        = $anchorKind
            Type              = if ($type -and $canonicalType.ContainsKey($type)) { $canonicalType[$type] }
            elseif ($type) { $type }
            elseif ($odataType -and $odataObjectType.ContainsKey($odataType)) { $odataObjectType[$odataType] }
            elseif ($odataType) { $odataType }
            else { 'Unknown' }
            Id                = $id
            DisplayName       = $displayName
            UserPrincipalName = $userPrincipalName
            PortalLink        = $portalLink
            Source            = 'GraphObjects'
        }
    }
    return @($records)
}
﻿function Get-MtPortalLinkTemplate {
    <#
    .SYNOPSIS
    Returns the shared portal deep-link templates and odata type mappings for known Graph object types.

    .DESCRIPTION
    Single source of truth for the GraphObjectType → admin portal deep-link mapping used by
    Get-GraphObjectMarkdown (markdown rendering) and Add-MtTestResultDetail (structured
    RelatedObjects records for the affected objects).

    Link templates use {0} as the placeholder for the object id. Types without {0}
    are tenant-level settings surfaces that have no per-object deep link.
    #>
    [CmdletBinding()]
    [OutputType([hashtable])]
    param()

    return @{
        # GraphObjectType → portal deep-link template ({0} = object id)
        LinkTemplates    = @{
            AuthenticationMethod = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_IAM/AuthenticationMethodsMenuBlade/~/AdminAuthMethods"
            AuthorizationPolicy  = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_UsersAndTenants/UserManagementMenuBlade/~/UserSettings/menuId/UserSettings"
            ConditionalAccess    = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_ConditionalAccess/PolicyBlade/policyId/{0}"
            ConsentPolicy        = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_IAM/ConsentPoliciesMenuBlade/~/UserSettings"
            Devices              = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_Devices/DeviceDetailsMenuBlade/~/Properties/objectId/{0}"
            Domains              = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_IAM/DomainsManagementMenuBlade/~/CustomDomainNames"
            Groups               = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_IAM/GroupDetailsMenuBlade/~/Overview/groupId/{0}"
            IdentityProtection   = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_IAM/IdentityProtectionMenuBlade/~/UsersAtRiskAlerts/fromNav/Identity"
            Users                = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_UsersAndTenants/UserProfileMenuBlade/~/overview/userId/{0}"
            UserRole             = "$($__MtSession.AdminPortalUrl.Entra)#view/Microsoft_AAD_UsersAndTenants/UserProfileMenuBlade/~/AdministrativeRole/userId/{0}"
        }
        # @odata.type → GraphObjectType (auto-detection when no explicit type is passed)
        OdataTypeMapping = @{
            '#microsoft.graph.user'   = 'Users'
            '#microsoft.graph.group'  = 'Groups'
            '#microsoft.graph.device' = 'Devices'
        }
        # GraphObjectType → whether the deep link addresses a single object instance
        # (types not listed here resolve to a tenant-level settings surface)
        InstanceTypes    = @('ConditionalAccess', 'Devices', 'Groups', 'Users', 'UserRole')
    }
}
﻿function Select-MtAffectedObjectByType {
    <#
    .SYNOPSIS
    Filters consolidated object records down to the types that count as an affected object.

    .DESCRIPTION
    Applies the catalog from Get-MtAffectedObjectTypeDefinition:
    - Types listed under ExcludedTypes are dropped silently (known findings, not objects).
    - For systems listed under KnownTypes, any other type is dropped and summarized in a
      warning so it can be triaged and added to the catalog.
    - Records of any other system pass through unchanged.

    .EXAMPLE
    Select-MtAffectedObjectByType -Objects $inventory

    Returns the inventory without Entra recommendations, PIM alerts and unknown types.
    #>
    [CmdletBinding()]
    [OutputType([object[]])]
    param(
        # Consolidated object records to filter.
        [Parameter(Mandatory = $false)]
        [AllowEmptyCollection()]
        [object[]] $Objects
    )

    if (-not $Objects) { return @() }

    $definition = Get-MtAffectedObjectTypeDefinition
    $kept = [System.Collections.Generic.List[object]]::new()
    $dropped = [System.Collections.Generic.List[object]]::new()

    foreach ($affectedObject in $Objects) {
        $system = [string]$affectedObject.System
        $type = [string]$affectedObject.Type

        if ($definition.ExcludedTypes.ContainsKey($system) -and $definition.ExcludedTypes[$system] -contains $type) {
            Write-Verbose "Affected objects: dropping excluded type $system/$type."
            continue
        }

        if ($definition.KnownTypes.ContainsKey($system) -and $definition.KnownTypes[$system] -notcontains $type) {
            $dropped.Add($affectedObject)
            continue
        }

        $kept.Add($affectedObject)
    }

    if ($dropped.Count -gt 0) {
        $summary = $dropped | Group-Object -Property { "$($_.System)/$($_.Type)" } |
            Sort-Object Name | ForEach-Object { "$($_.Name) ($($_.Count))" }
        Write-Warning ("Affected objects: {0} record(s) of unknown type were dropped: {1}. Add the type to Get-MtAffectedObjectTypeDefinition (KnownTypes) to inventory it, or to ExcludedTypes if it is not an affected object." -f $dropped.Count, ($summary -join ', '))
    }

    return , $kept.ToArray()
}

