// The facts behind a "2 risks" badge, for its tooltip.
function factTitle(o: AffectedObject, tone: Tone) {
    return o.facts
        .filter((fact) => toTone(fact.Tone) === tone)
        .map((fact) => `${fact.Name}: ${fact.Value}`)
        .join("\n")
}

